namespace NetScope {
 internal static class BrandIcon {
  public static readonly Icon Value=Create();
  [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool DestroyIcon(IntPtr handle);
  static Icon Create(){using(var bitmap=new Bitmap(64,64)){using(var g=Graphics.FromImage(bitmap)){g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Color.Transparent);using(var shape=Theme.Round(new RectangleF(2,2,60,60),14))using(var brush=new SolidBrush(Color.FromArgb(35,132,81)))g.FillPath(brush,shape);using(var pen=new Pen(Color.White,4.4f)){pen.StartCap=LineCap.Round;pen.EndCap=LineCap.Round;g.DrawArc(pen,12,13,40,31,210,120);g.DrawArc(pen,20,23,24,20,210,120);}using(var brush=new SolidBrush(Color.White))g.FillEllipse(brush,29,41,6,6);}IntPtr native=bitmap.GetHicon();try{using(var icon=Icon.FromHandle(native))return (Icon)icon.Clone();}finally{DestroyIcon(native);}}}
 }
 public class RoundedButton:Button {
  public bool Primary,Borderless; bool hovering;
  public RoundedButton(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;Cursor=Cursors.Hand;UseVisualStyleBackColor=false;}
  protected override void OnMouseEnter(EventArgs e){hovering=true;Invalidate();base.OnMouseEnter(e);}
  protected override void OnMouseLeave(EventArgs e){hovering=false;Invalidate();base.OnMouseLeave(e);}
  protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Parent==null?Theme.Back:Parent.BackColor.A==0?Theme.Card:Parent.BackColor);Color fill=Enabled?BackColor:Theme.Border;if(hovering&&Enabled)fill=Primary?ControlPaint.Light(fill,.08f):Color.FromArgb(Theme.IsDay?232:35,Theme.IsDay?241:52,Theme.IsDay?235:59);using(var shape=Theme.Round(new RectangleF(.5f,.5f,Math.Max(1,Width-1),Math.Max(1,Height-1)),8)){using(var brush=new SolidBrush(fill))g.FillPath(brush,shape);if(!Primary&&!Borderless)using(var pen=new Pen(Theme.Border))g.DrawPath(pen,shape);}var rect=new Rectangle(Padding.Left+6,4,Math.Max(1,Width-Padding.Horizontal-12),Math.Max(1,Height-8));TextFormatFlags flags=TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix|TextFormatFlags.NoPadding;flags|=TextAlign==ContentAlignment.MiddleLeft?TextFormatFlags.Left:TextFormatFlags.HorizontalCenter;TextRenderer.DrawText(g,Text,Font,rect,Enabled?ForeColor:Theme.Muted,flags);if(Focused&&ShowFocusCues)ControlPaint.DrawFocusRectangle(g,new Rectangle(4,4,Width-8,Height-8));}
 }
 public class HeroSurface:Panel {
  public HeroSurface(){DoubleBuffered=true;BackColor=Theme.Card;Padding=new Padding(22,18,22,18);}
  protected override void OnPaintBackground(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Parent==null?Theme.Back:Parent.BackColor);using(var shape=Theme.Round(new RectangleF(0,0,Math.Max(1,Width-1),Math.Max(1,Height-1)),16))using(var brush=new LinearGradientBrush(ClientRectangle,Theme.IsDay?Color.FromArgb(230,244,234):Color.FromArgb(25,49,46),Theme.Card,0f))g.FillPath(brush,shape);}
 }
 public class NetworkStatusOrb:Control {
  public string State="idle",Caption="待检查"; readonly Timer timer=new Timer();float angle;
  public NetworkStatusOrb(){SetStyle(ControlStyles.SupportsTransparentBackColor,true);DoubleBuffered=true;BackColor=Color.Transparent;Font=Theme.Font(11,FontStyle.Bold);timer.Interval=80;timer.Tick+=delegate{if(State=="busy"){angle=(angle+12)%360;Invalidate();}};timer.Start();}
  protected override void Dispose(bool disposing){if(disposing)timer.Dispose();base.Dispose(disposing);}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;float size=Math.Min(Width,Height)-20;float x=(Width-size)/2,y=(Height-size)/2;Color tone=State=="attention"?Theme.Amber:State=="idle"?Theme.Muted:Theme.Accent;using(var brush=new SolidBrush(Color.FromArgb(Theme.IsDay?18:28,tone)))g.FillEllipse(brush,x,y,size,size);using(var pen=new Pen(Color.FromArgb(Theme.IsDay?48:65,tone),3))g.DrawEllipse(pen,x+10,y+10,size-20,size-20);if(State=="busy")using(var pen=new Pen(tone,4)){pen.StartCap=LineCap.Round;pen.EndCap=LineCap.Round;g.DrawArc(pen,x+10,y+10,size-20,size-20,angle,90);}float cx=Width/2f,cy=Height/2f-14;using(var pen=new Pen(tone,3.2f)){pen.StartCap=LineCap.Round;pen.EndCap=LineCap.Round;g.DrawArc(pen,cx-33,cy-28,66,50,210,120);g.DrawArc(pen,cx-23,cy-16,46,35,212,116);g.DrawArc(pen,cx-12,cy-4,24,20,215,110);}using(var brush=new SolidBrush(tone))g.FillEllipse(brush,cx-4,cy+14,8,8);TextRenderer.DrawText(g,Caption,Font,new Rectangle((int)x+10,(int)(cy+34),(int)size-20,36),tone,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);}
 }
 public class InspectionRow:Panel {
  public readonly Label Headline=new Label(),Detail=new Label();public readonly RoundedButton ActionButton=new RoundedButton();
  readonly Label question=new Label(),number=new Label();readonly RoundedButton expand=new RoundedButton();public bool Expanded{get;private set;}public event Action ExpandedChanged;
  public InspectionRow(int index,string title){DoubleBuffered=true;BackColor=Theme.Card;Margin=Padding.Empty;Height=78;question.Text=title;question.Font=Theme.Font(10,FontStyle.Regular);question.ForeColor=Theme.Muted;question.TextAlign=ContentAlignment.MiddleLeft;question.AutoEllipsis=true;Headline.Font=Theme.Font(11,FontStyle.Bold);Headline.ForeColor=Theme.Text;Headline.TextAlign=ContentAlignment.MiddleLeft;Headline.AutoEllipsis=true;Headline.Text="等待检查";Detail.Font=Theme.Font(10,FontStyle.Regular);Detail.ForeColor=Theme.Muted;Detail.TextAlign=ContentAlignment.TopLeft;Detail.Visible=false;number.Text=index.ToString("00");number.Font=Theme.Font(11,FontStyle.Bold);number.ForeColor=Theme.Accent;number.TextAlign=ContentAlignment.MiddleCenter;ActionButton.Font=Theme.Font(10,FontStyle.Regular);ActionButton.BackColor=Theme.Card;ActionButton.ForeColor=Theme.Accent;ActionButton.Borderless=true;expand.Text="+";expand.Borderless=true;expand.Font=Theme.Font(12,FontStyle.Regular);expand.BackColor=Theme.Card;expand.ForeColor=Theme.Muted;expand.AccessibleName="展开或收起这项说明";expand.Click+=delegate{ToggleExpanded();};question.Click+=delegate{ToggleExpanded();};Headline.Click+=delegate{ToggleExpanded();};question.Cursor=Cursors.Hand;Headline.Cursor=Cursors.Hand;Controls.Add(number);Controls.Add(question);Controls.Add(Headline);Controls.Add(ActionButton);Controls.Add(expand);Controls.Add(Detail);SizeChanged+=delegate{LayoutParts();};}
  public void ToggleExpanded(){Expanded=!Expanded;Detail.Visible=Expanded;expand.Text=Expanded?"−":"+";Height=Expanded?140:78;LayoutParts();if(ExpandedChanged!=null)ExpandedChanged();Invalidate();}
  void LayoutParts(){int actionWidth=Width<760?116:150;int right=Width-actionWidth-47;number.SetBounds(10,11,42,50);question.SetBounds(64,7,Math.Max(1,right-75),27);Headline.SetBounds(64,32,Math.Max(1,right-75),36);ActionButton.SetBounds(right,17,actionWidth,42);expand.SetBounds(Width-42,18,34,40);Detail.SetBounds(64,80,Math.Max(1,Width-88),52);}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);using(var pen=new Pen(Theme.Border))e.Graphics.DrawLine(pen,62,Height-1,Width-18,Height-1);}
 }
